#include <iostream>
#include <string>
using namespace std;

class Rekening {
protected:
    int saldo;

public:
    Rekening(int awal) : saldo(awal) {
    }

    void setor(int jumlah) {
        saldo += jumlah;
    }

    bool tarik(int jumlah) {
        if (jumlah > saldo) {
            return false;
        }
        saldo -= jumlah;
        return true;
    }

    int lihat() const {
        return saldo;
    }
};

class Giro : public Rekening {
private:
    int batas;

public:
    Giro(int awal, int b) : Rekening(awal), batas(b) {
    }

    bool tarik(int jumlah) {
        if (saldo - jumlah < -batas) {
            return false;
        }
        saldo -= jumlah;
        return true;
    }
};

int main() {
    int awal, batas;
    cin >> awal >> batas;
    Giro giro(awal, batas);
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int jumlah;
        cin >> jumlah;
        if (perintah == "setor") {
            giro.setor(jumlah);
            cout << "Saldo: " << giro.lihat() << endl;
        } else if (giro.tarik(jumlah)) {
            cout << "Saldo: " << giro.lihat() << endl;
        } else {
            cout << "Ditolak" << endl;
        }
    }
    return 0;
}

