#include <iostream>
#include <string>
using namespace std;

class DaftarBilangan {
protected:
    int data[20];
    int banyak = 0;

public:
    void tambahBelakang(int x) {
        data[banyak] = x;
        banyak++;
    }

    int ambilDepan() {
        auto x = data[0];
        for (int k = 0; k < banyak - 1; k++) {
            data[k] = data[k + 1];
        }
        banyak--;
        return x;
    }

    int ambilBelakang() {
        banyak--;
        return data[banyak];
    }

    bool kosong() const {
        return banyak == 0;
    }

    int ukuran() const {
        return banyak;
    }
};

class Antrean : private DaftarBilangan {
public:
    using DaftarBilangan::kosong;
    using DaftarBilangan::ukuran;

    void masuk(int x) {
        tambahBelakang(x);
    }

    int keluar() {
        return ambilDepan();
    }
};

class Tumpukan : private DaftarBilangan {
public:
    using DaftarBilangan::kosong;
    using DaftarBilangan::ukuran;

    void dorong(int x) {
        tambahBelakang(x);
    }

    int ambil() {
        return ambilBelakang();
    }
};

int main() {
    Antrean antrean;
    Tumpukan tumpukan;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "antre" || perintah == "tumpuk") {
            int x;
            cin >> x;
            if (perintah == "antre") {
                antrean.masuk(x);
            } else {
                tumpukan.dorong(x);
            }
        } else if (perintah == "layani") {
            if (antrean.kosong()) {
                cout << "antrean kosong" << endl;
            } else {
                cout << antrean.keluar() << endl;
            }
        } else if (tumpukan.kosong()) {
            cout << "tumpukan kosong" << endl;
        } else {
            cout << tumpukan.ambil() << endl;
        }
    }
    cout << "Antrean: " << antrean.ukuran() << endl;
    cout << "Tumpukan: " << tumpukan.ukuran() << endl;
    return 0;
}

