class Printer {
protected:
    int kertas;

public:
    Printer(int k) : kertas(k) {
        cout << "+Printer" << endl;
    }

    ~Printer() {
        cout << "-Printer" << endl;
    }

    bool cetak(int halaman) {
        if (halaman > kertas) {
            cout << "Kertas kurang" << endl;
            return false;
        }
        kertas -= halaman;
        cout << "Mencetak " << halaman << " halaman" << endl;
        return true;
    }
};

class Pemindai {
protected:
    int dipindai = 0;

public:
    Pemindai() {
        cout << "+Pemindai" << endl;
    }

    ~Pemindai() {
        cout << "-Pemindai" << endl;
    }

    void pindai(int halaman) {
        dipindai += halaman;
        cout << "Memindai " << halaman << " halaman" << endl;
    }
};

class MesinSerbaguna : public Printer, public Pemindai {
private:
    string nama;

public:
    MesinSerbaguna(const string &n, int k) : Printer(k), nama(n) {
        cout << "+MesinSerbaguna " << nama << endl;
    }

    ~MesinSerbaguna() {
        cout << "-MesinSerbaguna " << nama << endl;
    }

    void salin(int halaman) {
        pindai(halaman);
        cetak(halaman);
    }

    void laporan() const {
        cout << "Kertas: " << kertas << ", dipindai: " << dipindai << endl;
    }
};

int main() {
    string nama;
    int kertas;
    cin >> nama >> kertas;
    MesinSerbaguna mesin(nama, kertas);
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int halaman;
        cin >> halaman;
        if (perintah == "cetak") {
            mesin.cetak(halaman);
        } else if (perintah == "pindai") {
            mesin.pindai(halaman);
        } else {
            mesin.salin(halaman);
        }
    }
    mesin.laporan();
    return 0;
}

