};

class Antrean : public Daftar {
public:
    void masuk(int x) {
        data[banyak] = x;
        banyak++;
    }

    int keluar() {
        auto x = data[0];
        for (int k = 0; k < banyak - 1; k++) {
            data[k] = data[k + 1];
        }
        banyak--;
        return x;
    }
};

class AntreanPrioritas : public Antrean {
public:
    void masuk(int x) {
        auto posisi = banyak;
        while (posisi > 0 && data[posisi - 1] < x) {
            data[posisi] = data[posisi - 1];
            posisi--;
        }
        data[posisi] = x;
        banyak++;
    }
};

