                    d = &dosen[k];
                }
            }
            if (p == nullptr || d == nullptr) {
                cout << "Tidak ditemukan" << endl;
            } else if (p->sudahDibimbing()) {
                cout << "Sudah punya pembimbing" << endl;
            } else if (!d->terimaBimbingan()) {
                cout << "Dosen penuh" << endl;
            } else {
                p->setPembimbing(d);
                cout << a << " dibimbing " << b << endl;
            }
            continue;
        }
        string nama;
        int id;
        cin >> nama >> id;
        if (perintah == "dosen") {
            dosen[nd].isi(nama, id);
            urutan[total] = 'd';
            nomor[total] = nd;
            nd++;
        } else if (perintah == "mahasiswa") {
            mahasiswa[nm].isi(nama, id);
            urutan[total] = 'm';
            nomor[total] = nm;
            nm++;
        } else {
            pasca[np].isi(nama, id);
            urutan[total] = 'p';
            nomor[total] = np;
            np++;
        }
        total++;
    }
    for (int k = 0; k < total; k++) {
        if (urutan[k] == 'd') {
            dosen[nomor[k]].cetak();
        } else if (urutan[k] == 'm') {
            mahasiswa[nomor[k]].cetak();
        } else {
            pasca[nomor[k]].cetak();
        }
        cout << endl;
    }
    cout << "Orang: " << Orang::banyak << ", dosen: " << nd << ", mahasiswa: " << nm + np << ", pascasarjana: " << np << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Robot {
protected:
    int posisi = 0;
    int baterai;

public:
    Robot(int b) : baterai(b) {
    }

    bool gerak(int langkah, int biaya) {
        if (langkah * biaya > baterai) {
            return false;
        }
        baterai -= langkah * biaya;
        posisi += langkah;
        return true;
    }

    bool maju(int langkah) {
        return gerak(langkah, 1);
    }

    int getPosisi() const {
        return posisi;
    }

    int getBaterai() const {
        return baterai;
    }
};

class RobotPengangkut : public Robot {
protected:
    int kapasitas;
    int muatan = 0;

public:
    RobotPengangkut(int b, int k) : Robot(b), kapasitas(k) {
    }

    bool angkat(int berat) {
        if (muatan > 0 || berat > kapasitas) {
            return false;
        }
        muatan = berat;
        return true;
    }

    int taruh() {
        auto berat = muatan;
        muatan = 0;
        return berat;
    }

    bool maju(int langkah) {
        if (muatan == 0) {
            return Robot::maju(langkah);
        }
        return gerak(langkah, 2);
    }
};

class RobotHemat : public RobotPengangkut {
private:
    int ditolak = 0;

public:
    RobotHemat(int b, int k) : RobotPengangkut(b, k) {
    }

    bool maju(int langkah) {
        auto biaya = 1;
        if (muatan > 0) {
            biaya = 2;
        }
        if (baterai - langkah * biaya < 10) {
            ditolak++;
            return false;
        }
        return RobotPengangkut::maju(langkah);
    }

    int getDitolak() const {
        return ditolak;
    }
};

int main() {
    int baterai, kapasitas;
    cin >> baterai >> kapasitas;
    RobotHemat robot(baterai, kapasitas);
    auto terantar = 0;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "taruh") {
            auto berat = robot.taruh();
            if (berat == 0) {
                cout << "Tidak membawa apa-apa" << endl;
            } else {
                terantar += berat;
                cout << "Menaruh " << berat << " kg di posisi " << robot.getPosisi() << endl;
            }
            continue;
        }
        int x;
        cin >> x;
        if (perintah == "angkat") {
            if (robot.angkat(x)) {
                cout << "Mengangkat " << x << " kg" << endl;
            } else {
                cout << "Tidak bisa mengangkat" << endl;
            }
        } else if (robot.maju(x)) {
            cout << "Posisi " << robot.getPosisi() << ", baterai " << robot.getBaterai() << endl;
        } else {
            cout << "Baterai dijaga" << endl;
        }
    }
    cout << "Terantar " << terantar << " kg, ditolak " << robot.getDitolak() << " kali" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Media {
protected:
    string judul;
    int tahun = 0;
    bool aktif = false;

public:
    void isiDasar(const string &j, int t) {
        judul = j;
        tahun = t;
        aktif = true;
    }

    string getJudul() const {
        return judul;
    }

    int getTahun() const {
        return tahun;
    }

    bool masihAda() const {
        return aktif;
    }

    void hapus() {
        aktif = false;
    }

    void cetak() const {
        cout << judul << " (" << tahun << ")";
    }
};

class Buku : public Media {
private:
    int halaman = 0;

public:
    void isi(const string &j, int t, int h) {
        isiDasar(j, t);
        halaman = h;
    }

    int menit() const {
        return halaman * 2;
    }

    void cetak() const {
        Media::cetak();
        cout << ", " << halaman << " halaman";
    }
};

class Film : public Media {
protected:
    int durasi = 0;

public:
    void isi(const string &j, int t, int d) {
        isiDasar(j, t);
        durasi = d;
    }

    int menit() const {
        return durasi;
    }

    void cetak() const {
        Media::cetak();
        cout << ", " << durasi << " menit";
    }
};

class FilmSeri : public Film {
private:
    int episode = 0;

public:
    void isi(const string &j, int t, int d, int e) {
        Film::isi(j, t, d);
        episode = e;
    }

    int menit() const {
        return Film::menit() * episode;
    }

    void cetak() const {
        Film::cetak();
        cout << " x " << episode << " episode";
    }
};

int main() {
    Buku buku[12];
    Film film[12];
    FilmSeri seri[12];
    auto nb = 0;
    auto nf = 0;
    auto ns = 0;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        string judul;
        cin >> judul;
        if (perintah == "hapus") {
            auto ketemu = false;
            for (int k = 0; k < nb; k++) {
                if (buku[k].masihAda() && buku[k].getJudul() == judul) {
                    buku[k].hapus();
                    ketemu = true;
                }
            }
            for (int k = 0; k < nf; k++) {
                if (film[k].masihAda() && film[k].getJudul() == judul) {
                    film[k].hapus();
                    ketemu = true;
                }
            }
            for (int k = 0; k < ns; k++) {
                if (seri[k].masihAda() && seri[k].getJudul() == judul) {
                    seri[k].hapus();
                    ketemu = true;
                }
            }
            if (ketemu) {
                cout << "Dihapus: " << judul << endl;
            } else {
                cout << "Tidak ada: " << judul << endl;
            }
            continue;
        }
        int tahun, a;
        cin >> tahun >> a;
        if (perintah == "buku") {
            buku[nb].isi(judul, tahun, a);
            nb++;
        } else if (perintah == "film") {
            film[nf].isi(judul, tahun, a);
            nf++;
        } else {
            int episode;
            cin >> episode;
            seri[ns].isi(judul, tahun, a, episode);
            ns++;
        }
    }
    auto total = 0;
    cout << "Buku:" << endl;
    for (int k = 0; k < nb; k++) {
        if (buku[k].masihAda()) {
            buku[k].cetak();
            cout << endl;
            total += buku[k].menit();
        }
    }
    cout << "Film:" << endl;
    for (int k = 0; k < nf; k++) {
        if (film[k].masihAda()) {
            film[k].cetak();
            cout << endl;
            total += film[k].menit();
        }
    }
    cout << "Seri:" << endl;
    for (int k = 0; k < ns; k++) {
        if (seri[k].masihAda()) {
            seri[k].cetak();
            cout << endl;
            total += seri[k].menit();
        }
    }
    cout << "Total: " << total / 60 << " jam " << total % 60 << " menit" << endl;
    return 0;
}
